select:
select 'jobAssignment' AS noticeType, DATE_FORMAT(ja.task_date,'%Y-%m-%d') as day from jml_job_assignment ja join jml_job_assignment_staff jas on ja.id = jas.job_assignment_id
jas.assigned_engineer_staff_id = #{staffId} and DATE_FORMAT(task_date,'%Y-%m') between #{lastMonth} and #{preMonth}
group by day
